import React, { useState } from 'react';
import styled from 'styled-components';
import { useNavigate } from 'react-router-dom';
import ResultComponent from './ResultComponent';

const PopUpContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopUpForm = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  width: 600px;
  max-height: 80%;
  overflow-y: auto;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background-color: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #888;

  &:hover {
    color: #000;
  }
`;

const Title = styled.h3`
  text-align: center;
  font-size: 30px;
  margin-bottom: 20px;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const TableHeader = styled.th`
  background-color: #f4f4f4;
  padding: 10px;
  text-align: left;
  font-weight: bold;
`;

const TableData = styled.td`
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid #ddd;
`;

const TableRow = styled.tr`
  &:hover {
    background-color: #f9f9f9;
  }
`;

const Icon = styled.span`
  cursor: pointer;
  margin-left: 20px;
  color: #007bff;
  font-size: 30px;
  &:hover {
    color: #0056b3;
  }
`;

const ExperimentInfo = ({ showModal, closeModal }) => {
  const experiments = [
    { name: 'Mẫu thí nghiệm 1', fastaFile: 'sample1.fasta' },
    { name: 'Mẫu thí nghiệm 2', fastaFile: 'sample2.fasta' },
    { name: 'Mẫu thí nghiệm 3', fastaFile: 'sample3.fasta' },
  ];
  const navigate = useNavigate();
  if (!showModal) return null;
  const [fastaInfo, setFastaInfo]= useState(
      {
      name: "Sample1",
      header: ">Sample1_header",
      length: 12345,
      createdAt: "2025-04-01T14:30:00Z"
      }
    );
    const [virulenceInfo, setVirulenceInfo]=useState(
      [
        {
          sequence: "ATCGATCGATCG",
          gene: "Gene1",
          start: 100,
          stop: 200,
          strand: "+",
          identity: 98.5,
          coverage: 85.2,
          accession: "NC_12345",
          product: "Protein A"
        },
        {
          sequence: "GCTAGCTAGCTA",
          gene: "Gene2",
          start: 250,
          stop: 350,
          strand: "-",
          identity: 95.7,
          coverage: 80.4,
          accession: "NC_67890",
          product: "Protein B"
        }
      ]   
    );
    const [amrInfo, setAmrInfo] = useState(
    [
      {
        Gene: "blaTEM-1",
        Resistance: "Yes",
        Antibiotic: "Ampicillin",
        Accession: "NC_000913",
        Product: "Beta-lactamase",
        Coverage: 85.5,
        Identity: 99.8,
      },
      {
        Gene: "qnrS1",
        Resistance: "No",
        Antibiotic: "Ciprofloxacin",
        Accession: "NC_010473",
        Product: "Quinolone resistance protein",
        Coverage: 92.3,
        Identity: 98.4,
      },
    ]
    );
  const [showResult, setShowResult] = useState(false)
  const handleGetResult = () =>{
    setShowResult(!showResult)
  }    
  return (
    <PopUpContainer>
      <PopUpForm>
        <CloseButton onClick={closeModal}>×</CloseButton>
        <Title>Thông Tin Thí Nghiệm</Title>
        <Table>
          <thead>
            <tr>
              <TableHeader>STT</TableHeader>
              <TableHeader>Tên Mẫu Thí Nghiệm</TableHeader>
              <TableHeader>Tên Tệp FASTA</TableHeader>
              <TableHeader>Chi Tiết</TableHeader>
            </tr>
          </thead>
          <tbody>
            {experiments.map((experiment, index) => (
              <TableRow key={index}>
                <TableData>{index + 1}</TableData>
                <TableData>{experiment.name}</TableData>
                <TableData>
                  {experiment.fastaFile}
                  <Icon onClick={() => alert('Tải xuống tệp FASTA')}>⤓</Icon>
                </TableData>
                <TableData>
                  <Icon onClick={() => handleGetResult()}>🔍</Icon>
                </TableData>
              </TableRow>
            ))}
          </tbody>
        </Table>
      </PopUpForm>
      //<ResultComponent fastaInfo={fastaInfo} virulenceInfo={virulenceInfo} amrInfo={amrInfo}/> 
    </PopUpContainer>
  );
};


export default ExperimentInfo;
